INSERT INTO "public"."activity_log" ("id", "company_id", "actor_type", "actor_id", "action", "entity_type", "entity_id", "agent_id", "details", "created_at", "run_id") VALUES ($paperclip$fb63617f-4a2b-4e3a-a94f-6a8d833e5ea4$paperclip$, $paperclip$1b42b2ec-221c-44ad-bc35-a007969be7c4$paperclip$, $paperclip$user$paperclip$, $paperclip$plJet0czEgiMwrdH8eeLywjLY7mkQRkD$paperclip$, $paperclip$issue.updated$paperclip$, $paperclip$issue$paperclip$, $paperclip$2d715a7f-1750-4574-82d0-eb0273ce1e2b$paperclip$, NULL, $paperclip${"_previous":{"description":"Create weekly routine template with 10 recurring time blocks (morning/evening routines, kids activities, meal planning, financial check-in, relationship touchpoints, exercise, personal admin, family time, weekly review). All slots TBD pending board customization.","assigneeAgentId":null},"identifier":"PER-3","description":"## Weekly Routine System\n\n**Status:** Template drafted with 10 time blocks — all TBD pending board customization.\n\n### 10 Recurring Time Blocks\n\n1. **Morning Routine** (Mon-Fri 6:30-8:00): Wake, exercise/stretch, breakfast, kids ready for school — *Need: wake time, kids' school start*\n2. **Evening Routine** (Daily 18:00-21:00): Dinner, homework help, bedtime routines — *Need: adjust for kids' ages*\n3. **Kids Activities** (TBD): Sports, lessons, tutoring — *Need: specific activities, locations, schedules*\n4. **Meal Planning** (Sunday AM): Weekly meal prep and grocery list — *Need: confirm day preference*\n5. **Financial Check-in** (Sunday PM/Monday AM): 15-30 min review spending, bills, budget — *Need: confirm day/time*\n6. **Relationship Touchpoints** (Wednesday): Reach out to one friend/family member — *Need: contact list*\n7. **Exercise/Fitness** (TBD, 3-4x/week): — *Need: preferred activity and schedule*\n8. **Personal Admin** (Saturday AM): Errands, appointments, mail, returns — *Need: confirm window*\n9. **Family Time** (Sat/Sun PM): No work, no screens — *Need: confirm preferred window*\n10. **Weekly Review with EA** (Sunday PM): Upcoming week preview, action items, reminders\n\n### Next Steps\n- Board provides wake time, exercise preferences, kids' schedules\n- EA activates blocks as they're confirmed\n- Move from draft to active status","assigneeAgentId":"b92f97f4-2de8-4520-98fc-06910ee68499"}$paperclip$, $paperclip$2026-04-03T19:43:55.167Z$paperclip$, NULL);
-- paperclip statement breakpoint 69f6f3f1-42fd-46a6-bf17-d1d85f8f3900
INSERT INTO "public"."activity_log" ("id", "company_id", "actor_type", "actor_id", "action", "entity_type", "entity_id", "agent_id", "details", "created_at", "run_id") VALUES ($paperclip$624a4266-4b36-4ad4-8996-54556e3ec596$paperclip$, $paperclip$1b42b2ec-221c-44ad-bc35-a007969be7c4$paperclip$, $paperclip$user$paperclip$, $paperclip$plJet0czEgiMwrdH8eeLywjLY7mkQRkD$paperclip$, $paperclip$issue.updated$paperclip$, $paperclip$issue$paperclip$, $paperclip$cd274f30-cd31-48ef-8331-5897100ff79c$paperclip$, NULL, $paperclip${"_previous":{"description":"Build financial management system. Files: budget.yaml, bills.yaml, savings-goals.yaml, subscriptions.yaml. 12 budget categories. All values TBD pending board input.","assigneeAgentId":null},"identifier":"PER-4","description":"## Financial Dashboard\n\n**Status:** Template created with 12 budget categories — all values TBD.\n\n### Budget Categories\n1. Housing (rent/mortgage, utilities, maintenance)\n2. Food & Groceries\n3. Transportation (car payment, gas, transit, parking)\n4. Education (tuition, school supplies, tutoring)\n5. Childcare (daycare, babysitting, activities)\n6. Healthcare (insurance premiums, copays, prescriptions)\n7. Insurance (life, auto, home, umbrella)\n8. Entertainment & Leisure\n9. Personal Care\n10. Gifts & Donations\n11. Savings & Investments\n12. Miscellaneous\n\n### Files Created\n- `finances/budget.yaml` — Monthly budget template\n- `finances/bills.yaml` — Recurring bills tracker\n- `finances/savings-goals.yaml` — Savings targets\n- `finances/subscriptions.yaml` — Subscription inventory\n\n### Awaiting Board Input\n- [ ] Monthly income figure\n- [ ] Budget amounts for each category\n- [ ] Recurring bill details (amounts, due dates)\n- [ ] Savings goals and targets\n- [ ] Current subscriptions list","assigneeAgentId":"b92f97f4-2de8-4520-98fc-06910ee68499"}$paperclip$, $paperclip$2026-04-03T19:43:55.397Z$paperclip$, NULL);
-- paperclip statement breakpoint 69f6f3f1-42fd-46a6-bf17-d1d85f8f3900
INSERT INTO "public"."activity_log" ("id", "company_id", "actor_type", "actor_id", "action", "entity_type", "entity_id", "agent_id", "details", "created_at", "run_id") VALUES ($paperclip$eff0a9ff-d083-4e25-99b1-8ab9e830a88c$paperclip$, $paperclip$1b42b2ec-221c-44ad-bc35-a007969be7c4$paperclip$, $paperclip$user$paperclip$, $paperclip$plJet0czEgiMwrdH8eeLywjLY7mkQRkD$paperclip$, $paperclip$issue.updated$paperclip$, $paperclip$issue$paperclip$, $paperclip$298f77d5-69f4-430d-928c-9814eae8214f$paperclip$, NULL, $paperclip${"_previous":{"description":"Build relationship contact management system. YAML profiles with contact info, birthdays, gifts, touchpoints, reminders. Awaiting board input on inner circle contacts.","assigneeAgentId":null},"identifier":"PER-5","description":"## Relationship CRM\n\n**Status:** Schema defined, 2 profiles created — awaiting inner circle contacts.\n\n### Existing Profiles\n- **Jessica** — Girlfriend. Birthday Nov 23. Anniversary Feb 24. Interests: clothes, KITH, sneakers. Contact via text. *Privacy: must NOT know about agents.*\n- **Ivory** — Board member. Birthday Jan 23. NYC-based.\n\n### CRM Schema (per contact)\n- Name, relationship type, category (inner-circle/close/acquaintance)\n- Birthday, anniversary, contact info (phone, email, preferred method)\n- Interests, conversation topics, dietary preferences\n- Gift preferences and history\n- Touchpoint tracking: last contact, frequency goal, next reminder, history\n- Kids info\n\n### Awaiting Board Input\n- [ ] Inner circle contacts (family, close friends)\n- [ ] Contact details for each person\n- [ ] Touchpoint frequency preferences\n- [ ] Gift history and preferences\n- [ ] Any professional contacts to track","assigneeAgentId":"b92f97f4-2de8-4520-98fc-06910ee68499"}$paperclip$, $paperclip$2026-04-03T19:43:55.492Z$paperclip$, NULL);
-- paperclip statement breakpoint 69f6f3f1-42fd-46a6-bf17-d1d85f8f3900
INSERT INTO "public"."activity_log" ("id", "company_id", "actor_type", "actor_id", "action", "entity_type", "entity_id", "agent_id", "details", "created_at", "run_id") VALUES ($paperclip$9d152631-e0e2-4ebe-bb3c-7ac69b85fda7$paperclip$, $paperclip$1b42b2ec-221c-44ad-bc35-a007969be7c4$paperclip$, $paperclip$user$paperclip$, $paperclip$plJet0czEgiMwrdH8eeLywjLY7mkQRkD$paperclip$, $paperclip$issue.updated$paperclip$, $paperclip$issue$paperclip$, $paperclip$a0432ced-c262-45f6-9164-cc9cde92c17a$paperclip$, NULL, $paperclip${"_previous":{"description":"Create family calendar and schedule management. 5 YAML files (school, activities, medical, family-events, travel). All files empty pending board input.","assigneeAgentId":null},"identifier":"PER-6","description":"## Family Calendar System\n\n**Status:** 5 calendar files created — all empty, awaiting board input.\n\n### Calendar Categories\n1. **School** (`school.yaml`) — School terms, holidays, parent-teacher conferences, early dismissals\n2. **Activities** (`activities.yaml`) — Kids' recurring activities: sports, lessons, tutoring, clubs\n3. **Medical** (`medical.yaml`) — Doctor/dentist appointments, vaccination schedules, check-ups\n4. **Family Events** (`family-events.yaml`) — Birthdays, reunions, holidays, celebrations\n5. **Travel** (`travel.yaml`) — Trips, school breaks, vacation planning windows\n\n### Integration\n- Syncs with Apple Calendar for scheduling\n- Reminders set with configurable lead time\n- YAML-based atomic facts with dates and notes\n\n### Awaiting Board Input\n- [ ] Kids' school name(s) and calendar\n- [ ] Recurring activity schedules\n- [ ] Upcoming medical appointments\n- [ ] Family birthdays and events\n- [ ] Travel plans and school break dates","assigneeAgentId":"b92f97f4-2de8-4520-98fc-06910ee68499"}$paperclip$, $paperclip$2026-04-03T19:43:55.540Z$paperclip$, NULL);
-- paperclip statement breakpoint 69f6f3f1-42fd-46a6-bf17-d1d85f8f3900
INSERT INTO "public"."activity_log" ("id", "company_id", "actor_type", "actor_id", "action", "entity_type", "entity_id", "agent_id", "details", "created_at", "run_id") VALUES ($paperclip$55ba2595-8581-4cf1-a3a7-9e93d407e7df$paperclip$, $paperclip$1b42b2ec-221c-44ad-bc35-a007969be7c4$paperclip$, $paperclip$user$paperclip$, $paperclip$plJet0czEgiMwrdH8eeLywjLY7mkQRkD$paperclip$, $paperclip$issue.updated$paperclip$, $paperclip$issue$paperclip$, $paperclip$2b4ef292-dcc4-4e5c-9774-b083e84bbfa3$paperclip$, NULL, $paperclip${"_previous":{"description":"Set up PARA memory structure. Initialized directory structure, created index.md and daily notes template. Awaiting board input on personal information.","assigneeAgentId":null},"identifier":"PER-2","description":"## Personal Knowledge Base (PARA System)\n\n**Status:** Structure initialized, awaiting board input to populate.\n\n### What's Done\n- PARA directory structure created (Projects, Areas, Resources, Archives)\n- Knowledge graph index at life/index.md\n- People profiles: Ivory (birthday Jan 23) and Jessica (birthday Nov 23, anniversary Feb 24)\n- Relationship resource: date night preferences, restaurant checklist, travel bucket list, drinks spots, key dates\n- Weekly routine template: 10 recurring time blocks drafted\n- Financial dashboard: 12 budget categories templated\n- Family calendar: 5 YAML files (school, activities, medical, family-events, travel)\n\n### Awaiting Board Input\n- Inner circle contacts for Relationship CRM\n- Financial figures for budget categories\n- Weekly routine customization (wake times, exercise, kids' schedules)\n- Family calendar data\n- Personal goals and projects","assigneeAgentId":"b92f97f4-2de8-4520-98fc-06910ee68499"}$paperclip$, $paperclip$2026-04-03T19:44:50.864Z$paperclip$, NULL);
